<?php
declare(strict_types=1);

function aiPublic(array $c): array {unset($c['secret']);$c['version']=(int)$c['version'];$c['shared']=(bool)$c['shared'];$c['active']=(bool)$c['active'];return $c;}
function aiBase(string $provider,string $base): string {
    if($provider==='openai')return 'https://api.openai.com/v1';if($provider==='anthropic')return 'https://api.anthropic.com/v1';
    $p=parse_url(rtrim($base,'/'));if($provider!=='daimon'||!is_array($p)||($p['scheme']??'')!=='https'||(isset($p['user'])||isset($p['pass']))||isset($p['port'])||isset($p['query'])||isset($p['fragment'])||!preg_match('/^[a-z0-9-]+\.daimon\.intelligence-gmbh\.com$/D',$p['host']??'')||!preg_match('~^/vllm/[a-zA-Z0-9_-]+/v1$~D',$p['path']??''))fail(422,'Daimon benötigt eine HTTPS-Modelladresse unter *.daimon.intelligence-gmbh.com/vllm/…/v1.');return rtrim($base,'/');
}
function aiConnectionSave(array $u,array $data): array {
    needFeature($u,'ai');$cid=textField($data,'id',32,false);$old=$cid?one('SELECT * FROM ai_connections WHERE id=? AND user_id=?',[$cid,$u['id']]):null;if($cid&&!$old)fail(404,'Verbindung nicht gefunden.');
    $shared=$data['shared']??false;if(isset($data['active'])&&!is_bool($data['active']))fail(422,'Ungültiger Verbindungsstatus.');if(!is_bool($shared)||($shared&&!in_array($u['role'],['teacher','admin'],true)))fail(403,'Nur Dozenten dürfen Projektverbindungen bereitstellen.');$provider=textField($data,'provider',20);if(($provider==='daimon'||($old['provider']??'')==='daimon')&&$u['role']!=='admin')fail(403,'Daimon-Zugänge werden ausschließlich von Administratoren verwaltet.');$base=aiBase($provider,textField($data,'base_url',300,false));$cap=$data['capability']??'chat';if(!in_array($cap,['chat','embedding','rerank'],true)||($provider==='anthropic'&&$cap!=='chat')||($provider==='openai'&&$cap==='rerank'))fail(422,'Dieser Anbieter unterstützt diese Funktion hier nicht.');
    $key=textField($data,'key',500,false);if($old&&$key===''&&($old['provider']!==$provider||$old['base_url']!==$base))fail(422,'Bei einem anderen Anbieter oder Server bitte einen neuen passenden Schlüssel eingeben.');if($key!==''&&preg_match('/\s/',$key))fail(422,'Ungültiger API-Schlüssel.');if(!$old&&$key==='')fail(422,'Bitte einen API-Schlüssel eingeben.');
    return transaction(function()use($u,$data,$cid,$old,$shared,$provider,$base,$cap,$key){$current=$cid?one('SELECT * FROM ai_connections WHERE id=? AND user_id=?',[$cid,$u['id']]):null;if($cid&&!$current)fail(404,'Verbindung nicht gefunden.');if($old&&(($data['version']??null)!==(int)$current['version']||(int)$old['version']!==(int)$current['version']))fail(409,'Die Verbindung wurde inzwischen geändert.');if(!$old&&(int)query('SELECT COUNT(*) FROM ai_connections WHERE user_id=?',[$u['id']])->fetchColumn()>=20)fail(413,'Höchstens 20 Verbindungen pro Konto.');$id=$cid?:id();$secret=$key!==''?encryptSecret($key):$old['secret'];
        if($old){query('UPDATE ai_connections SET name=?,provider=?,base_url=?,model=?,capability=?,secret=?,shared=?,active=?,version=version+1 WHERE id=?',[labName($data['name']??null),$provider,$base,labName($data['model']??null,120),$cap,$secret,(int)$shared,(int)($data['active']??true),$id]);if(!$shared)query('DELETE FROM ai_grants WHERE connection_id=?',[$id]);}else query('INSERT INTO ai_connections(id,user_id,name,provider,base_url,model,capability,secret,shared,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],labName($data['name']??null),$provider,$base,labName($data['model']??null,120),$cap,$secret,(int)$shared,now()]);audit($u['id'],'ai.connection.save');return aiPublic(one('SELECT * FROM ai_connections WHERE id=?',[$id]));});
}
function aiAvailable(array $u,string $pid): array {
    labAccess($u,$pid);needFeature($u,'ai');return array_map(fn($c)=>$c['user_id']===$u['id']?aiPublic($c):array_intersect_key(aiPublic($c),array_flip(['id','name','provider','model','capability'])),all('SELECT DISTINCT c.* FROM ai_connections c JOIN users owner ON owner.id=c.user_id LEFT JOIN ai_grants g ON g.connection_id=c.id AND g.project_id=? WHERE c.active=1 AND owner.active=1 AND (c.provider<>"daimon" OR owner.role="admin") AND (c.user_id=? OR (owner.role IN ("teacher","admin") AND c.shared=1 AND g.project_id IS NOT NULL)) ORDER BY c.name',[$pid,$u['id']]));
}
function aiHttp(array $c,string $path,array $payload): array {
    if(!extension_loaded('curl'))fail(503,'Die PHP-cURL-Erweiterung fehlt.');$base=aiBase($c['provider'],$c['base_url']);$host=parse_url($base,PHP_URL_HOST);$ips=gethostbynamel($host);if(!$ips)fail(503,'Der KI-Dienst ist nicht erreichbar.');foreach($ips as $ip)if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))fail(403,'Die KI-Adresse ist nicht öffentlich erreichbar.');
    $headers=['Content-Type: application/json'];$secret=decryptSecret($c['secret']);$headers[]=$c['provider']==='anthropic'?'x-api-key: '.$secret:'Authorization: Bearer '.$secret;if($c['provider']==='anthropic')$headers[]='anthropic-version: 2023-06-01';
    $body='';$ch=curl_init($base.$path);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_THROW_ON_ERROR),CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>45,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_RESOLVE=>[$host.':443:'.$ips[0]],CURLOPT_WRITEFUNCTION=>static function($handle,$part)use(&$body){if(strlen($body)+strlen($part)>2097152)return 0;$body.=$part;return strlen($part);}]);$ok=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
    if($ok===false)fail(503,'Der KI-Dienst antwortet nicht rechtzeitig.');if($status<200||$status>=300)fail($status===429?429:422,match($status){401,403=>'Der KI-Zugang wurde vom Anbieter abgelehnt.',429=>'Der KI-Anbieter ist ausgelastet. Bitte später erneut versuchen.',default=>'Der KI-Dienst konnte diese Anfrage nicht verarbeiten (HTTP '.$status.').'});try{$out=json_decode($body,true,64,JSON_THROW_ON_ERROR);}catch(JsonException){fail(502,'Ungültige Antwort des KI-Dienstes.');}if(!is_array($out))fail(502,'Ungültige Antwort des KI-Dienstes.');return $out;
}
function aiRun(array $u,array $data,?callable $transport=null): array {
    $pid=textField($data,'project',32);labAccess($u,$pid);needFeature($u,'ai');$cid=textField($data,'connection',32);if(!in_array($cid,array_column(aiAvailable($u,$pid),'id'),true))fail(403,'Diese KI-Verbindung ist für das Projekt nicht freigegeben.');$c=one('SELECT * FROM ai_connections WHERE id=?',[$cid]);$op=$data['operation']??'chat';$projectConfig=json_decode(one('SELECT config FROM lab_project_config WHERE project_id=?',[$pid])['config']??'{}',true);if(isset($projectConfig['tools'])&&!array_intersect($projectConfig['tools'],$op==='chat'?['prompt','rag']:['rag']))fail(403,'KI ist in diesem Projekt nicht aktiviert.');if($op!==$c['capability'])fail(422,'Die Verbindung unterstützt diese Operation nicht.');if($op!=='chat')needFeature($u,'rag');
    $payload=['model'=>$c['model']];$path='';if($op==='chat'){$prompt=textField($data,'prompt',30000);$system=textField($data,'system',4000,false);if($c['provider']==='anthropic'){$path='/messages';$payload+=['max_tokens'=>1024,'system'=>$system,'messages'=>[['role'=>'user','content'=>$prompt]]];}elseif($c['provider']==='openai'){$path='/responses';$payload+=['input'=>$prompt,'instructions'=>$system,'max_output_tokens'=>1024,'store'=>false];}else{$path='/chat/completions';$payload+=['max_tokens'=>1024,'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$prompt]]];}}
    elseif($op==='embedding'){$inputs=labList($data['input']??[],20);if(!$inputs)fail(422,'Bitte Texte angeben.');foreach($inputs as $text)if(!is_string($text)||trim($text)===''||mb_strlen($text)>12000)fail(422,'Ungültiger Textabschnitt.');$path='/embeddings';$payload+=['input'=>$inputs];}
    else{$documents=labList($data['documents']??[],20);foreach($documents as $text)if(!is_string($text)||mb_strlen($text)>12000)fail(422,'Ungültiger Textabschnitt.');$path='/rerank';$payload+=['query'=>textField($data,'query',4000),'documents'=>$documents];}
    $request=textField($data,'request',32);if(!preg_match('/^[a-f0-9]{32}$/D',$request))fail(422,'Ungültige Anfragekennung.');rateLimit('ai.'.$u['id'],30,60);
    $cached=transaction(function()use($u,$pid,$cid,$request,$c){if(!in_array($cid,array_column(aiAvailable($u,$pid),'id'),true))fail(403,'Diese KI-Verbindung ist nicht mehr freigegeben.');$current=one('SELECT version FROM ai_connections WHERE id=?',[$cid]);if(!$current||(int)$current['version']!==(int)$c['version'])fail(409,'Die KI-Verbindung wurde inzwischen geändert. Bitte erneut auswählen.');query("UPDATE ai_calls SET state='archived',result=NULL WHERE state='done' AND created<?",[time()-604800]);$old=one('SELECT * FROM ai_calls WHERE id=?',[$request]);if($old){if($old['user_id']!==$u['id']||$old['project_id']!==$pid||$old['connection_id']!==$cid)fail(409,'Anfragekennung bereits verwendet.');if($old['state']==='done')return json_decode($old['result'],true);fail(409,'Diese Anfrage wurde bereits gestartet. Bitte ihren Status prüfen.');}
        query("UPDATE ai_calls SET state='expired' WHERE state='running' AND created<?",[time()-120]);if((int)query("SELECT COUNT(*) FROM ai_calls WHERE state='running'")->fetchColumn()>=labLimits()['parallel'])fail(429,'Alle KI-Plätze sind belegt. Die Anfrage wartet.');$grant=one('SELECT max_calls FROM ai_grants WHERE project_id=? AND connection_id=?',[$pid,$cid]);if($grant&&(int)query('SELECT COUNT(*) FROM ai_calls WHERE project_id=? AND connection_id=?',[$pid,$cid])->fetchColumn()>=(int)$grant['max_calls'])fail(403,'Das Anfragebudget dieses Projekts ist ausgeschöpft.');if(workspaceBytes(labAccess($u,$pid))+1048576>SPACE_LIMIT)fail(413,'Für den KI-Aufruf fehlt freier Workspace-Speicher (1 MB Reserve).');query('INSERT INTO ai_calls(id,user_id,project_id,connection_id,state,created) VALUES(?,?,?,?,?,?)',[$request,$u['id'],$pid,$cid,'running',time()]);return null;});if($cached!==null)return $cached;
    if(session_status()===PHP_SESSION_ACTIVE)session_write_close();
    try{$started=microtime(true);$raw=$transport?$transport($c,$path,$payload):aiHttp($c,$path,$payload);$result=['operation'=>$op,'model'=>$c['model'],'ms'=>(int)((microtime(true)-$started)*1000),'tokens'=>(int)($raw['usage']['total_tokens']??(($raw['usage']['input_tokens']??0)+($raw['usage']['output_tokens']??0)))];
        if($op==='chat'){$text=$raw['choices'][0]['message']['content']??null;if($c['provider']==='anthropic')$text=implode('',array_column(array_filter($raw['content']??[],fn($b)=>($b['type']??'')==='text'),'text'));if($c['provider']==='openai'){$text='';foreach($raw['output']??[] as $item)foreach($item['content']??[] as $part)if(($part['type']??'')==='output_text')$text.=$part['text'];}if(!is_string($text)||strlen($text)>100000)fail(502,'Ungültige Modellantwort.');$result['text']=$text;}
        elseif($op==='embedding'){$vectors=$raw['data']??[];usort($vectors,fn($a,$b)=>($a['index']??0)<=>($b['index']??0));if(count($vectors)!==count($payload['input']))fail(502,'Unvollständige Embeddings.');$result['vectors']=[];$dim=null;foreach($vectors as $i=>$v){if(($v['index']??$i)!==$i)fail(502,'Ungültige Embedding-Reihenfolge.');$vector=labList($v['embedding']??[],4096);if(!$vector||($dim!==null&&count($vector)!==$dim))fail(502,'Ungültige Embedding-Dimension.');foreach($vector as $n)labNumeric($n);$dim=count($vector);$result['vectors'][]=$vector;}}
        else{$result['results']=$raw['results']??$raw['data']??[];foreach(labList($result['results'],20) as $r){if(!is_int($r['index']??null)||$r['index']<0||$r['index']>=count($payload['documents']))fail(502,'Ungültige Reranking-Antwort.');labNumeric($r['relevance_score']??$r['score']??null);}}
        $encoded=json_encode($result,JSON_THROW_ON_ERROR);if(strlen($encoded)>1048576)fail(413,'Die Modellantwort ist zu groß. Weniger Textabschnitte pro Aufruf verwenden.');query("UPDATE ai_calls SET state='done',result=?,tokens=? WHERE id=?",[$encoded,$result['tokens'],$request]);return $result;
    }catch(Throwable $e){query("UPDATE ai_calls SET state='failed' WHERE id=?",[$request]);throw $e;}
}
